def choose_move(observation):
    def _pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def _dir(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def _manhattan(p, qx, qy):
        return abs(p[0] - qx) + abs(p[1] - qy)

    def _nearest(points, sx, sy):
        best = None
        best_d = None
        for p in points:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                d = abs(p[0] - sx) + abs(p[1] - sy)
                if best is None or d < best_d:
                    best = p
                    best_d = d
        return best

    def _farthest(points, sx, sy):
        best = None
        best_d = None
        for p in points:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                d = abs(p[0] - sx) + abs(p[1] - sy)
                if best is None or d > best_d:
                    best = p
                    best_d = d
        return best

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name", "resource_collection")
    sx, sy = _pair(obs.get("self_position", (0, 0)))
    ox, oy = _pair(obs.get("opponent_position", (sx, sy)))
    w = obs.get("grid_width", 0)
    h = obs.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = obs.get("self_role", "pursuer")
        if role == "pursuer":
            return [_dir(sx, ox), _dir(sy, oy)]
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = _farthest(corners, ox, oy)
        if target is None:
            return [0, 0]
        return [_dir(sx, target[0]), _dir(sy, target[1])]

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "border_cells", "frontier_cells", "targets"):
            vals = obs.get(key)
            if isinstance(vals, (list, tuple)):
