        if not candidates:
            for key in ("opponent_position", "self_position"):
                p = obs.get(key)
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    candidates.append(p)
        target = _nearest(candidates, sx, sy)
        if target is None:
            return [0, 0]
        return [_dir(sx, target[0]), _dir(sy, target[1])]

    resources = []
    for key in ("resources", "resource_cells", "resource_positions", "points"):
        vals = obs.get(key)
        if isinstance(vals, (list, tuple)):
            resources.extend(vals)

    if resources:
        target = _nearest(resources, sx, sy)
        if target is not None:
            return [_dir(sx, target[0]), _dir(sy, target[1])]

    # Fallbacks: move toward opponent, or stay still if no useful info.
    if ox != sx or oy != sy:
        return [_dir(sx, ox), _dir(sy, oy)]
    return [0, 0]

